#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;

    // Convert headers
    html = std::regex_replace(html, std::regex(R"(^# (.+)$)"), R"(<h1>$1</h1>)");
    html = std::regex_replace(html, std::regex(R"(^## (.+)$)"), R"(<h2>$1</h2>)");
    html = std::regex_replace(html, std::regex(R"(^### (.+)$)"), R"(<h3>$1</h3>)");

    // Convert bold text
    html = std::regex_replace(html, std::regex(R"(\*\*(.+?)\*\*)"), R"(<strong>$1</strong>)");

    // Convert italic text
    html = std::regex_replace(html, std::regex(R"(\*(.+?)\*)"), R"(<em>$1</em>)");

    return html;
}

int main() {
